"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[387],{6958:e=>{e.exports=JSON.parse('{"tag":{"label":"build","permalink":"/docs/pr-preview/pr-303/tags/build","allTagsPath":"/docs/pr-preview/pr-303/tags","count":3,"items":[{"id":"new-to-cartesi/overview","title":"Cartesi","description":"Cartesi, is a L2 platform for the development and deployment of scalable decentralized applications. It offers a Linux operating system coupled with a blockchain infrastructure, which allows dApps to be developed in familiar programming languages like Python without the need to write Solidity code.","permalink":"/docs/pr-preview/pr-303/new-to-cartesi/overview"},{"id":"new-to-cartesi/onboarding","title":"Choose your Onboarding Path","description":"Our onboarding paths answer the following questions:","permalink":"/docs/pr-preview/pr-303/new-to-cartesi/onboarding"},{"id":"new-to-cartesi/scalability","title":"Scalability","description":"The scalability issue is one of the three parts of the Blockchain Trilemma, along with security and decentralization. Solving the scalability issue refers to any type of improvement within a blockchain system in terms of computational power, throughput, latency, bootstrap time, or cost per transaction. For example, high gas fees make it expensive for users to pay for their transactions within the Ethereum blockchain.","permalink":"/docs/pr-preview/pr-303/new-to-cartesi/scalability"}],"unlisted":false}}')}}]);